import { ChangeDetectionStrategy, Component, computed, signal } from '@angular/core';

type Cell = 'X' | 'O' | null;

@Component({
  selector: 'app-root',
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  readonly board = signal<Cell[]>(Array.from({ length: 9 }, () => null));
  readonly currentPlayer = signal<'X' | 'O'>('X');

  readonly winner = computed(() => this.calculateWinner(this.board()));
  readonly isDraw = computed(() => !this.winner() && this.board().every((c) => c !== null));
  readonly isGameOver = computed(() => !!this.winner() || this.isDraw());
  readonly status = computed(() => {
    const winner = this.winner();
    if (winner) return `Winner: ${winner}`;
    if (this.isDraw()) return 'Draw';
    return `Next: ${this.currentPlayer()}`;
  });

  play(i: number): void {
    if (this.isGameOver()) return;
    if (this.board()[i] !== null) return;

    const mark = this.currentPlayer();
    // Replace the array instead of writing into it, so winner, isDraw and status see the move.
    this.board.update((board) => board.map((cell, index) => (index === i ? mark : cell)));

    if (!this.isGameOver()) {
      this.currentPlayer.set(mark === 'X' ? 'O' : 'X');
    }
  }

  reset(): void {
    this.board.set(Array.from({ length: 9 }, () => null));
    this.currentPlayer.set('X');
  }

  private calculateWinner(b: Cell[]): 'X' | 'O' | null {
    const lines: number[][] = [
      [0, 1, 2],
      [3, 4, 5],
      [6, 7, 8],
      [0, 3, 6],
      [1, 4, 7],
      [2, 5, 8],
      [0, 4, 8],
      [2, 4, 6]
    ];

    for (const [a, c, d] of lines) {
      const v = b[a];
      if (v && v === b[c] && v === b[d]) return v;
    }

    return null;
  }
}
